import React from 'react';
import Particles from 'react-tsparticles';
import { loadFull } from 'tsparticles';
import { styled } from '@mui/material/styles';

const ParticleContainer = styled('div')`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
  pointer-events: none;
`;

const ParticleEffect = ({ isActive }) => {
  const particlesInit = async (main) => {
    await loadFull(main);
  };

  if (!isActive) return null;

  return (
    <ParticleContainer>
      <Particles
        id="tsparticles"
        init={particlesInit}
        options={{
          background: {
            color: {
              value: 'transparent',
            },
          },
          fpsLimit: 60,
          particles: {
            color: {
              value: '#00f7ff',
            },
            links: {
              color: '#00f7ff',
              distance: 150,
              enable: true,
              opacity: 0.2,
              width: 1,
            },
            move: {
              enable: true,
              outModes: {
                default: 'bounce',
              },
              random: false,
              speed: 1,
              straight: false,
            },
            number: {
              density: {
                enable: true,
                area: 800,
              },
              value: 80,
            },
            opacity: {
              value: 0.3,
            },
            shape: {
              type: 'circle',
            },
            size: {
              value: { min: 1, max: 3 },
            },
          },
          detectRetina: true,
        }}
      />
    </ParticleContainer>
  );
};

export default ParticleEffect; 