const generateBotResponse = (userMessage, selectedContact) => {
  const lowercaseMessage = userMessage.toLowerCase();
  const responses = {
    'Tech & AI Forum': {
      greetings: ['Hello! Ready to discuss tech and AI?', 'Welcome to the Tech & AI Forum!', 'Hi there, tech enthusiast!'],
      keywords: {
        'ai': ['AI is revolutionizing many industries. What aspects interest you most?', 'The future of AI looks promising. Have you worked with any AI tools?'],
        'machine learning': ['Machine learning is fascinating. Are you working on any ML projects?', 'There are many exciting applications of ML. What area interests you?'],
        'programming': ['What programming languages do you work with?', 'Software development is constantly evolving. What\'s your take on modern development practices?'],
        'blockchain': ['Blockchain technology has many applications beyond cryptocurrency. What\'s your view on its potential?'],
        'default': ['That\'s an interesting perspective on technology. Tell me more.', 'How do you see this impacting the future of tech?']
      }
    },
    'Climate & Environment': {
      greetings: ['Welcome to the Climate discussion!', 'Hello, environmental advocate!', 'Ready to discuss climate action?'],
      keywords: {
        'climate': ['Climate change is a critical issue. What actions do you think are most urgent?', 'How do you think we can better address climate challenges?'],
        'renewable': ['Renewable energy is crucial for our future. What\'s your take on recent developments?'],
        'sustainable': ['Sustainability is key. How do you incorporate sustainable practices in your life?'],
        'default': ['Environmental protection is crucial. What are your thoughts on this?', 'That\'s an interesting perspective on environmental issues.']
      }
    },
    'Global Politics': {
      greetings: ['Welcome to the Global Politics discussion!', 'Hello, political analyst!', 'Ready to discuss world affairs?'],
      keywords: {
        'democracy': ['Democratic systems are complex. What\'s your view on current challenges?'],
        'policy': ['Policy changes can have far-reaching effects. What\'s your analysis?'],
        'default': ['That\'s an interesting perspective on global affairs.', 'How do you think this will impact international relations?']
      }
    },
    'Space Exploration': {
      greetings: ['Welcome, space enthusiast!', 'Ready to explore the cosmos?', 'Hello, fellow space explorer!'],
      keywords: {
        'mars': ['Mars exploration is fascinating. What aspects interest you most?'],
        'nasa': ['NASA has many exciting projects. Which ones are you following?'],
        'space': ['Space exploration opens up endless possibilities. What excites you most about it?'],
        'default': ['The universe is full of mysteries. What are your thoughts on this?']
      }
    },
    'Health & Wellness': {
      greetings: ['Welcome to Health & Wellness!', 'Hello, wellness seeker!', 'Ready to discuss health topics?'],
      keywords: {
        'fitness': ['Fitness is crucial for overall health. What\'s your preferred workout routine?'],
        'nutrition': ['Nutrition plays a vital role in wellness. What\'s your approach to healthy eating?'],
        'default': ['Health and wellness are personal journeys. What\'s your experience?']
      }
    },
    'Arts & Culture': {
      greetings: ['Welcome, art enthusiast!', 'Hello, culture explorer!', 'Ready to discuss arts and culture?'],
      keywords: {
        'art': ['Art takes many forms. What styles resonate with you?'],
        'music': ['Music is a universal language. What genres do you enjoy?'],
        'default': ['Cultural expression is fascinating. What aspects interest you most?']
      }
    },
    'Sports & Athletics': {
      greetings: ['Welcome, sports fan!', 'Hello, athletics enthusiast!', 'Ready to discuss sports?'],
      keywords: {
        'sports': ['Sports bring people together. What teams do you follow?'],
        'game': ['That was an interesting game. What did you think of the strategy?'],
        'default': ['Sports and athletics are always exciting to discuss. What\'s your take?']
      }
    },
    'Business & Economy': {
      greetings: ['Welcome to Business & Economy!', 'Hello, business minded!', 'Ready to discuss economic trends?'],
      keywords: {
        'market': ['Markets are always evolving. What trends are you watching?'],
        'business': ['Business strategies are crucial. What\'s your approach?'],
        'economy': ['Economic factors impact everything. What\'s your analysis?'],
        'default': ['That\'s an interesting perspective on business and economics.']
      }
    }
  };

  // Get the appropriate responses for the selected forum
  const forumResponses = responses[selectedContact.name] || responses['Tech & AI Forum'];

  // Check if it's a greeting
  if (lowercaseMessage.match(/^(hi|hello|hey|greetings).*/)) {
    return forumResponses.greetings[Math.floor(Math.random() * forumResponses.greetings.length)];
  }

  // Check for keywords
  for (const [keyword, responses] of Object.entries(forumResponses.keywords)) {
    if (lowercaseMessage.includes(keyword)) {
      return responses[Math.floor(Math.random() * responses.length)];
    }
  }

  // Return default response if no keyword matches
  return forumResponses.keywords.default[Math.floor(Math.random() * forumResponses.keywords.default.length)];
};

