function Chat() {
  const [messages, setMessages] = useState([]);
  const [message, setMessage] = useState('');
  const [username] = useState(localStorage.getItem('username'));
  const [selectedContact, setSelectedContact] = useState(BOT_USERS[0]);
  const [typingUsers, setTypingUsers] = useState(new Set());
  const messagesEndRef = useRef(null);
  const navigate = useNavigate();
  const [showMatrix, setShowMatrix] = useState(false);
  const [showParticles, setShowParticles] = useState(true);
  const [showAnalytics, setShowAnalytics] = useState(false);
  const location = useLocation();
  const [isTyping, setIsTyping] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Load messages for the selected contact
  useEffect(() => {
    if (selectedContact) {
      const savedMessages = localStorage.getItem(`chatMessages_${selectedContact.id}`);
      if (savedMessages) {
        setMessages(JSON.parse(savedMessages));
      } else {
        // Add welcome message for first-time chat
        const welcomeMessage = {
          id: 1,
          sender: selectedContact.name,
          text: `Welcome to ${selectedContact.name}! ${selectedContact.description}`,
          timestamp: new Date().toISOString(),
          status: 'received',
        };
        setMessages([welcomeMessage]);
      }
    } else {
      setMessages([]);
    }
  }, [selectedContact]);

  // Save messages to localStorage whenever they change
  useEffect(() => {
    if (selectedContact) {
      localStorage.setItem(`chatMessages_${selectedContact.id}`, JSON.stringify(messages));
    }
  }, [messages, selectedContact]);

  useEffect(() => {
    if (!username) {
      navigate('/');
      return;
    }

    socket.emit('join', username);

    socket.on('message', (message) => {
      if (message.sender === username || message.sender === selectedContact?.name) {
        setMessages(prev => [...prev, message]);
      }
    });

    socket.on('typing', ({ user, isTyping }) => {
      setTypingUsers(prev => {
        const newSet = new Set(prev);
        if (isTyping) {
          newSet.add(user);
        } else {
          newSet.delete(user);
        }
        return newSet;
      });
    });

    socket.on('userJoined', ({ username, timestamp }) => {
      setMessages(prev => [...prev, {
        text: `${username} joined the chat`,
        sender: 'System',
        timestamp,
        isSystem: true
      }]);
    });

    socket.on('userLeft', ({ username, timestamp }) => {
      setMessages(prev => [...prev, {
        text: `${username} left the chat`,
        sender: 'System',
        timestamp,
        isSystem: true
      }]);
    });

    return () => {
      socket.off('message');
      socket.off('typing');
      socket.off('userJoined');
      socket.off('userLeft');
    };
  }, [username, navigate, selectedContact]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSendMessage = () => {
    if (message.trim() !== '' && selectedContact) {
      const newMessage = {
        id: messages.length + 1,
        sender: username,
        text: message,
        timestamp: new Date().toISOString(),
        status: 'sent',
      };

      setMessages(prevMessages => [...prevMessages, newMessage]);
      setMessage('');

      // Show typing indicator
      setIsTyping(true);

      // Simulate bot response with typing delay
      const typingDuration = Math.max(1500, message.length * 50); // Longer messages = longer typing time
      
      setTimeout(() => {
        const botResponse = {
          id: messages.length + 2,
          sender: selectedContact.name,
          text: generateBotResponse(message, selectedContact),
          timestamp: new Date().toISOString(),
          status: 'received',
        };
        setIsTyping(false);
        setMessages(prevMessages => [...prevMessages, botResponse]);
      }, typingDuration);
    }
  };

  const handleKeyPress = (event) => {
    if (event.key === 'Enter' && !event.shiftKey) {
      event.preventDefault();
      handleSendMessage();
    }
  };

  const handleContactSelect = (contact) => {
    setSelectedContact(contact);
    // Close mobile menu when a contact is selected
    setIsMobileMenuOpen(false);
  };

  const handleLogout = () => {
    localStorage.removeItem('username');
    navigate('/');
  };

  const handleClearChat = () => {
    if (selectedContact) {
      setMessages([]);
      localStorage.removeItem(`chatMessages_${selectedContact.id}`);
    }
  };

  const formatTime = (timestamp) => {
    return new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  // Add toggle function for mobile menu
  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  return (
    <GlobalScrollbarStyle>
      <Box sx={cssVariables}>
        <ChatContainer>
          <ParticleEffect isActive={showParticles} />
          <MatrixRain isActive={showMatrix} onClose={() => setShowMatrix(false)} />

          {!isMobileMenuOpen && (
            <HamburgerButton
              onClick={toggleMobileMenu}
              aria-label="open menu"
            >
              <MenuIcon />
            </HamburgerButton>
          )}

          <ResponsiveDrawer
            variant="permanent"
            isOpen={isMobileMenuOpen}
            onClose={() => setIsMobileMenuOpen(false)}
          >
            <AppBar position="static" color="default" elevation={1} sx={{ 
              background: 'rgba(26, 31, 53, 0.95)',
              backdropFilter: 'blur(10px)',
              borderBottom: '1px solid rgba(255, 255, 255, 0.1)',
              position: 'relative'
            }}>
              <Toolbar sx={{ 
                display: 'flex', 
                alignItems: 'center',
                justifyContent: 'space-between',
                px: 2 
              }}>
                <Box sx={{ 
                  display: 'flex', 
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  flex: 1
                }}>
                  <Typography 
                    variant="h6" 
                    noWrap 
                    component="div" 
                    sx={{ 
                      color: '#fff', 
                      fontFamily: 'Orbitron, sans-serif',
                      background: 'linear-gradient(45deg, #00f2fe 30%, #4facfe 90%)',
                      WebkitBackgroundClip: 'text',
                      WebkitTextFillColor: 'transparent',
                      backgroundSize: '200% 200%',
                      animation: `${gradientShift} 3s ease infinite`,
                    }}
                  >
                    CyberChat
                  </Typography>

                  <IconButton
                    onClick={handleLogout}
                    aria-label="logout"
                    sx={{ 
                      color: 'var(--neon-blue)',
                      ml: 2,
                      '&:hover': {
                        backgroundColor: 'rgba(0, 247, 255, 0.1)',
                      },
                    }}
                  >
                    <LogoutIcon />
                  </IconButton>
                </Box>

                {isMobileMenuOpen && (
                  <CloseButton
                    onClick={toggleMobileMenu}
                    aria-label="close menu"
                  >
                    <CloseIcon />
                  </CloseButton>
                )}
              </Toolbar>
            </AppBar>
            <Divider sx={{ borderColor: 'rgba(255, 255, 255, 0.1)' }} />
            <ScrollableBox sx={{ flex: 1, overflow: 'auto' }}>
              <List>
                {BOT_USERS.map((contact) => (
                  <ListItem key={contact.id} disablePadding>
                    <ListItemButton
                      selected={selectedContact?.id === contact.id}
                      onClick={() => handleContactSelect(contact)}
                      sx={{
                        transition: 'all 0.2s ease-in-out',
                        '&.Mui-selected': {
                          background: 'linear-gradient(45deg, rgba(0, 242, 254, 0.1) 30%, rgba(79, 172, 254, 0.1) 90%)',
                          '&:hover': {
                            background: 'linear-gradient(45deg, rgba(0, 242, 254, 0.15) 30%, rgba(79, 172, 254, 0.15) 90%)',
                            transform: 'translateX(5px)',
                          },
                        },
                        '&:hover': {
                          transform: 'translateX(5px)',
                        },
                      }}
                    >
                      <ListItemAvatar>
                        <Avatar 
                          sx={{ 
                            background: 'linear-gradient(45deg, #00f2fe 30%, #4facfe 90%)',
                            backgroundSize: '200% 200%',
                            animation: `${gradientShift} 3s ease infinite`,
                            color: '#fff',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                          }}
                        >
                          <SmartToyIcon sx={{ fontSize: 20 }} />
                        </Avatar>
                      </ListItemAvatar>
                      <ListItemText
                        primary={contact.name}
                        secondary={contact.description}
                        primaryTypographyProps={{ 
                          sx: { 
                            color: '#fff',
                            fontWeight: 'bold',
                            fontSize: '1.1rem'
                          } 
                        }}
                        secondaryTypographyProps={{ 
                          sx: { 
                            color: 'rgba(255, 255, 255, 0.5)',
                            fontSize: '0.9rem'
                          } 
                        }}
                      />
                    </ListItemButton>
                  </ListItem>
                ))}
              </List>
            </ScrollableBox>
          </ResponsiveDrawer>

          <Box sx={{ flexGrow: 1, display: 'flex', flexDirection: 'column' }}>
            {/* Desktop header - hidden on mobile */}
            <AppBar position="static" color="default" elevation={1} sx={{ 
              background: 'rgba(26, 31, 53, 0.95)',
              backdropFilter: 'blur(10px)',
              borderBottom: '1px solid rgba(255, 255, 255, 0.1)',
              display: { xs: 'none', md: 'block' }
            }}>
              <Toolbar>
                {selectedContact && (
                  <>
                    <Avatar 
                      sx={{ 
                        mr: 2, 
                        background: 'linear-gradient(45deg, #00f2fe 30%, #4facfe 90%)',
                        backgroundSize: '200% 200%',
                        animation: `${gradientShift} 3s ease infinite`,
                        color: '#fff',
                      }}
                    >
                      {selectedContact.name[0]}
                    </Avatar>
                    <Typography variant="h6" component="div" sx={{ color: '#fff', fontFamily: 'Rajdhani, sans-serif', flexGrow: 1 }}>
                      {selectedContact.name}
                    </Typography>
                    <IconButton
                      edge="end"
                      color="inherit"
                      aria-label="analytics"
                      onClick={() => setShowAnalytics(!showAnalytics)}
                      sx={{ 
                        color: showAnalytics ? '#00f7ff' : 'rgba(255, 255, 255, 0.7)',
                        mr: 1,
                        '&:hover': {
                          color: '#00f7ff',
                          backgroundColor: 'rgba(0, 247, 255, 0.1)',
                        },
                      }}
                    >
                      <BarChartIcon />
                    </IconButton>
                    <IconButton
                      edge="end"
                      color="inherit"
                      aria-label="chat"
                      onClick={() => setShowAnalytics(false)}
                      sx={{ 
                        color: !showAnalytics ? '#00f7ff' : 'rgba(255, 255, 255, 0.7)',
                        mr: 1,
                        '&:hover': {
                          color: '#00f7ff',
                          backgroundColor: 'rgba(0, 247, 255, 0.1)',
                        },
                      }}
                    >
                      <ChatIcon />
                    </IconButton>
                    <IconButton
                      edge="end"
                      color="inherit"
                      aria-label="clear chat"
                      onClick={handleClearChat}
                      sx={{ 
                        color: 'rgba(255, 255, 255, 0.7)',
                        '&:hover': {
                          color: '#ff6b6b',
                          backgroundColor: 'rgba(255, 107, 107, 0.1)',
                        },
                      }}
                    >
                      <DeleteOutlineIcon />
                    </IconButton>
                  </>
                )}
              </Toolbar>
            </AppBar>

            {/* Mobile header - shown only on mobile */}
            {selectedContact && (
              <MobileChatHeader position="static" elevation={1}>
                <Toolbar sx={{ 
                  display: 'flex', 
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  minHeight: '56px',
                  pl: '52px',
                }}>
                  <Typography 
                    variant="h6" 
                    sx={{ 
                      color: '#fff',
                      fontFamily: 'Rajdhani, sans-serif',
                      fontSize: '1.1rem',
                      ml: 1,
                      lineHeight: 1,
                    }}
                  >
                    {selectedContact.name}
                  </Typography>

                  <Box sx={{ display: 'flex', gap: 1 }}>
                    <IconButton
                      onClick={() => setShowAnalytics(!showAnalytics)}
                      sx={{ 
                        color: showAnalytics ? '#00f7ff' : 'rgba(255, 255, 255, 0.7)',
                        '&:hover': {
                          color: '#00f7ff',
                          backgroundColor: 'rgba(0, 247, 255, 0.1)',
                        },
                      }}
                    >
                      <BarChartIcon />
                    </IconButton>
                    <IconButton
                      onClick={() => setShowAnalytics(false)}
                      sx={{ 
                        color: !showAnalytics ? '#00f7ff' : 'rgba(255, 255, 255, 0.7)',
                        '&:hover': {
                          color: '#00f7ff',
                          backgroundColor: 'rgba(0, 247, 255, 0.1)',
                        },
                      }}
                    >
                      <ChatIcon />
                    </IconButton>
                    <IconButton
                      onClick={handleClearChat}
                      sx={{ 
                        color: 'rgba(255, 255, 255, 0.7)',
                        '&:hover': {
                          color: '#ff6b6b',
                          backgroundColor: 'rgba(255, 107, 107, 0.1)',
                        },
                      }}
                    >
                      <DeleteOutlineIcon />
                    </IconButton>
                  </Box>
                </Toolbar>
              </MobileChatHeader>
            )}

            {showAnalytics ? (
              <AnalyticsDashboard 
                messages={messages}
                selectedContact={selectedContact}
                username={username}
                allContacts={BOT_USERS}
              />
            ) : (
              <>
                <Box sx={{ 
                  flexGrow: 1, 
                  overflow: 'auto', 
                  p: 3,
                  background: 'linear-gradient(135deg, rgba(26, 31, 53, 0.9) 0%, rgba(36, 43, 74, 0.9) 100%)',
                  backdropFilter: 'blur(10px)',
                  display: 'flex',
                  flexDirection: 'column',
                }}>
                  <Box sx={{ flexGrow: 1, overflow: 'auto' }}>
                    {messages.map((msg, index) => (
                      <Box
                        key={msg.id || index}
                        sx={{
                          display: 'flex',
                          justifyContent: msg.sender === username ? 'flex-end' : 'flex-start',
                          mb: 2,
                          opacity: 1,
                          alignItems: 'flex-start',
                          gap: 1,
                          animation: `${slideIn} 0.3s ease-out`,
                        }}
                      >
                        {msg.sender !== username && (
                          <Avatar 
                            sx={{ 
                              width: 32,
                              height: 32,
                              background: 'linear-gradient(45deg, #00f2fe 30%, #4facfe 90%)',
                              backgroundSize: '200% 200%',
                              animation: `${gradientShift} 3s ease infinite`,
                              color: '#fff',
                              fontSize: '0.9rem',
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'center',
                            }}
                          >
                            <SmartToyIcon sx={{ fontSize: 18 }} />
                          </Avatar>
                        )}
                        <Box
                          sx={{
                            maxWidth: '70%',
                            p: 2,
                            borderRadius: '16px',
                            background: msg.sender === username
                              ? 'linear-gradient(135deg, rgba(0, 247, 255, 0.15) 0%, rgba(79, 172, 254, 0.15) 100%)'
                              : 'linear-gradient(135deg, rgba(255, 255, 255, 0.1) 0%, rgba(255, 255, 255, 0.05) 100%)',
                            backdropFilter: 'blur(10px)',
                            border: '1px solid',
                            borderColor: msg.sender === username
                              ? 'rgba(0, 247, 255, 0.2)'
                              : 'rgba(255, 255, 255, 0.1)',
                            color: '#fff',
                            ml: msg.sender === username ? 0 : '0',
                            mr: msg.sender === username ? '0' : 0,
                          }}
                        >
                          {msg.sender !== username && (
                            <Typography variant="caption" sx={{ 
                              display: 'block', 
                              color: 'rgba(0, 247, 255, 0.7)',
                              mb: 0.5,
                              fontWeight: 'bold'
                            }}>
                              {msg.sender}
                            </Typography>
                          )}
                          <Typography variant="body1" sx={{ wordBreak: 'break-word' }}>
                            {msg.text}
                          </Typography>
                          <Box sx={{ 
                            display: 'flex', 
                            alignItems: 'center', 
                            justifyContent: 'flex-end',
                            mt: 1,
                            gap: 0.5,
                          }}>
                            <Typography variant="caption" sx={{ color: 'rgba(255, 255, 255, 0.5)' }}>
                              {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                            </Typography>
                            {msg.sender === username && (
                              <DoneAllIcon sx={{ 
                                fontSize: 16, 
                                color: msg.status === 'read' ? '#00f7ff' : 'rgba(255, 255, 255, 0.5)',
                              }} />
                            )}
                          </Box>
                        </Box>
                        {msg.sender === username && (
                          <Avatar 
                            sx={{ 
                              width: 32,
                              height: 32,
                              background: 'linear-gradient(45deg, #4facfe 30%, #00f2fe 90%)',
                              backgroundSize: '200% 200%',
                              animation: `${gradientShift} 3s ease infinite`,
                              color: '#fff',
                              fontSize: '0.9rem',
                            }}
                          >
                            {username[0].toUpperCase()}
                          </Avatar>
                        )}
                      </Box>
                    ))}
                    {isTyping && <TypingIndicator />}
                  </Box>
                </Box>

                <Box sx={{ 
                  p: 2, 
                  background: 'rgba(255, 255, 255, 0.05)',
                  backdropFilter: 'blur(10px)',
                  borderTop: '1px solid rgba(255, 255, 255, 0.1)',
                }}>
                  <Box sx={{ 
                    display: 'flex', 
                    gap: 1,
                    alignItems: 'center',
                  }}>
                    <TextField
                      fullWidth
                      variant="outlined"
                      placeholder="Type a message..."
                      value={message}
                      onChange={(e) => setMessage(e.target.value)}
                      onKeyPress={handleKeyPress}
                      multiline
                      maxRows={4}
                      sx={{
                        '& .MuiOutlinedInput-root': {
                          color: '#fff',
                          backgroundColor: 'rgba(255, 255, 255, 0.05)',
                          '& fieldset': {
                            borderColor: 'rgba(255, 255, 255, 0.1)',
                          },
                          '&:hover fieldset': {
                            borderColor: 'rgba(0, 247, 255, 0.5)',
                          },
                          '&.Mui-focused fieldset': {
                            borderColor: '#00f7ff',
                          },
                        },
                        '& .MuiOutlinedInput-input': {
                          '&::placeholder': {
                            color: 'rgba(255, 255, 255, 0.5)',
                            opacity: 1,
                          },
                        },
                      }}
                    />
                    <IconButton 
                      onClick={handleSendMessage}
                      sx={{
                        backgroundColor: '#00f7ff',
                        color: '#1a1f35',
                        '&:hover': {
                          backgroundColor: 'rgba(0, 247, 255, 0.8)',
                        },
                      }}
                    >
                      <SendIcon />
                    </IconButton>
                  </Box>
                </Box>
              </>
            )}
          </Box>
        </ChatContainer>
      </Box>
    </GlobalScrollbarStyle>
  );
}

export default Chat; 