import React, { useEffect, useState } from 'react';
import {
  Box,
  Typography,
  Grid,
  Paper,
  CircularProgress,
  LinearProgress,
  List,
  ListItem,
  ListItemText,
} from '@mui/material';
import { styled } from '@mui/material/styles';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  PieChart,
  Pie,
  Cell,
  LineChart,
  Line,
  ResponsiveContainer,
} from 'recharts';

const GlassPaper = styled(Paper)(({ theme }) => ({
  background: 'rgba(255, 255, 255, 0.05)',
  backdropFilter: 'blur(10px)',
  borderRadius: '16px',
  padding: theme.spacing(3),
  color: '#fff',
  border: '1px solid rgba(255, 255, 255, 0.1)',
}));

const COLORS = ['#00f2fe', '#4facfe', '#00e5ff', '#00b8d4', '#0088a3'];

function AnalyticsDashboard({ messages, selectedContact, username, allContacts }) {
  const [analytics, setAnalytics] = useState({
    messageCount: 0,
    responseRate: 0,
    averageResponseTime: 0,
    messagesByHour: [],
    topKeywords: [],
    sentimentAnalysis: [],
    messageDistribution: [],
    activityTimeline: [],
  });

  useEffect(() => {
    if (!messages || !selectedContact) return;

    // Process messages to generate analytics
    const processAnalytics = () => {
      // Message count by user
      const userMessages = messages.filter(msg => msg.sender === username).length;
      const botMessages = messages.filter(msg => msg.sender === selectedContact.name).length;
      const totalMessages = messages.length;

      // Response rate
      const responseRate = botMessages > 0 ? (botMessages / userMessages) * 100 : 0;

      // Average response time
      let totalResponseTime = 0;
      let responseCount = 0;
      for (let i = 1; i < messages.length; i++) {
        if (messages[i].sender === selectedContact.name && messages[i-1].sender === username) {
          const timeDiff = new Date(messages[i].timestamp) - new Date(messages[i-1].timestamp);
          totalResponseTime += timeDiff;
          responseCount++;
        }
      }
      const averageResponseTime = responseCount > 0 ? totalResponseTime / responseCount : 0;

      // Messages by hour
      const hourCounts = new Array(24).fill(0);
      messages.forEach(msg => {
        const hour = new Date(msg.timestamp).getHours();
        hourCounts[hour]++;
      });
      const messagesByHour = hourCounts.map((count, hour) => ({
        hour: `${hour}:00`,
        count,
      }));

      // Extract keywords and count frequency
      const keywords = messages.reduce((acc, msg) => {
        const words = msg.text.toLowerCase()
          .split(/\s+/)
          .filter(word => word.length > 3 && !['the', 'and', 'for', 'that'].includes(word));
        words.forEach(word => {
          acc[word] = (acc[word] || 0) + 1;
        });
        return acc;
      }, {});
      const topKeywords = Object.entries(keywords)
        .sort(([, a], [, b]) => b - a)
        .slice(0, 5)
        .map(([keyword, count]) => ({ keyword, count }));

      // Message distribution
      const messageDistribution = [
        { name: 'User Messages', value: userMessages },
        { name: 'Bot Messages', value: botMessages },
      ];

      // Activity timeline (last 7 days)
      const timeline = new Array(7).fill(0).map((_, index) => {
        const date = new Date();
        date.setDate(date.getDate() - index);
        const count = messages.filter(msg => {
          const msgDate = new Date(msg.timestamp);
          return msgDate.toDateString() === date.toDateString();
        }).length;
        return {
          date: date.toLocaleDateString('en-US', { weekday: 'short' }),
          count,
        };
      }).reverse();

      setAnalytics({
        messageCount: totalMessages,
        responseRate,
        averageResponseTime,
        messagesByHour,
        topKeywords,
        messageDistribution,
        activityTimeline: timeline,
      });
    };

    processAnalytics();
  }, [messages, selectedContact, username]);

  return (
    <Box sx={{ 
      p: 3, 
      height: '100%', 
      overflow: 'auto',
      display: 'flex',
      flexDirection: 'column',
      gap: 3,
    }}>
      {/* Summary Cards Row */}
      <Grid container spacing={3}>
        <Grid item xs={12} sm={6} md={3}>
          <GlassPaper sx={{ height: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'center', p: 3 }}>
            <Typography variant="h6" gutterBottom sx={{ color: 'rgba(255, 255, 255, 0.7)' }}>
              Total Messages
            </Typography>
            <Typography variant="h3" sx={{ color: '#00f2fe', fontWeight: 'bold' }}>
              {analytics.messageCount}
            </Typography>
          </GlassPaper>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <GlassPaper sx={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', p: 3 }}>
            <Typography variant="h6" gutterBottom sx={{ color: 'rgba(255, 255, 255, 0.7)' }}>
              Response Rate
            </Typography>
            <Box sx={{ position: 'relative', display: 'inline-flex' }}>
              <CircularProgress
                variant="determinate"
                value={analytics.responseRate}
                sx={{ 
                  color: '#00f2fe',
                  '& .MuiCircularProgress-circle': {
                    strokeLinecap: 'round',
                  },
                }}
                size={80}
                thickness={4}
              />
              <Box sx={{
                position: 'absolute',
                top: 0,
                left: 0,
                bottom: 0,
                right: 0,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}>
                <Typography variant="h5" sx={{ color: '#fff', fontWeight: 'bold' }}>
                  {Math.round(analytics.responseRate)}%
                </Typography>
              </Box>
            </Box>
          </GlassPaper>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <GlassPaper sx={{ height: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'center', p: 3 }}>
            <Typography variant="h6" gutterBottom sx={{ color: 'rgba(255, 255, 255, 0.7)' }}>
              Avg Response Time
            </Typography>
            <Typography variant="h4" sx={{ color: '#00f2fe', fontWeight: 'bold' }}>
              {(analytics.averageResponseTime / 1000).toFixed(1)}s
            </Typography>
          </GlassPaper>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <GlassPaper sx={{ height: '100%', p: 3 }}>
            <Typography variant="h6" gutterBottom sx={{ color: 'rgba(255, 255, 255, 0.7)' }}>
              Top Keywords
            </Typography>
            <List dense sx={{ mt: 1 }}>
              {analytics.topKeywords.map((item, index) => (
                <ListItem key={item.keyword} sx={{ px: 0 }}>
                  <ListItemText
                    primary={
                      <Typography variant="body2" sx={{ color: '#fff', mb: 0.5 }}>
                        {item.keyword}
                      </Typography>
                    }
                    secondary={
                      <LinearProgress
                        variant="determinate"
                        value={(item.count / analytics.topKeywords[0].count) * 100}
                        sx={{
                          height: 6,
                          borderRadius: 3,
                          backgroundColor: 'rgba(255, 255, 255, 0.1)',
                          '& .MuiLinearProgress-bar': {
                            backgroundColor: COLORS[index % COLORS.length],
                            borderRadius: 3,
                          },
                        }}
                      />
                    }
                  />
                </ListItem>
              ))}
            </List>
          </GlassPaper>
        </Grid>
      </Grid>

      {/* Charts Row */}
      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          <GlassPaper sx={{ p: 3, height: '400px' }}>
            <Typography variant="h6" gutterBottom sx={{ color: 'rgba(255, 255, 255, 0.7)' }}>
              Message Distribution
            </Typography>
            <Box sx={{ height: 'calc(100% - 40px)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={analytics.messageDistribution}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    outerRadius={120}
                    fill="#8884d8"
                    label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                    labelLine={false}
                  >
                    {analytics.messageDistribution.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip 
                    contentStyle={{ 
                      background: 'rgba(26, 31, 53, 0.95)', 
                      border: '1px solid rgba(255, 255, 255, 0.1)',
                      borderRadius: '8px',
                      boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
                    }} 
                    itemStyle={{ color: '#fff' }}
                  />
                </PieChart>
              </ResponsiveContainer>
            </Box>
          </GlassPaper>
        </Grid>

        <Grid item xs={12} md={6}>
          <GlassPaper sx={{ p: 3, height: '400px' }}>
            <Typography variant="h6" gutterBottom sx={{ color: 'rgba(255, 255, 255, 0.7)' }}>
              Activity Timeline
            </Typography>
            <Box sx={{ height: 'calc(100% - 40px)' }}>
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={analytics.activityTimeline}>
                  <CartesianGrid strokeDasharray="3 3" stroke="rgba(255, 255, 255, 0.1)" />
                  <XAxis 
                    dataKey="date" 
                    stroke="#fff" 
                    tick={{ fill: '#fff' }}
                    axisLine={{ stroke: 'rgba(255, 255, 255, 0.1)' }}
                  />
                  <YAxis 
                    stroke="#fff"
                    tick={{ fill: '#fff' }}
                    axisLine={{ stroke: 'rgba(255, 255, 255, 0.1)' }}
                  />
                  <Tooltip
                    contentStyle={{ 
                      background: 'rgba(26, 31, 53, 0.95)', 
                      border: '1px solid rgba(255, 255, 255, 0.1)',
                      borderRadius: '8px',
                      boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
                    }}
                    itemStyle={{ color: '#fff' }}
                  />
                  <Line 
                    type="monotone" 
                    dataKey="count" 
                    stroke="#00f2fe" 
                    strokeWidth={2}
                    dot={{ fill: '#00f2fe', strokeWidth: 2 }}
                    activeDot={{ r: 6, fill: '#00f2fe' }}
                  />
                </LineChart>
              </ResponsiveContainer>
            </Box>
          </GlassPaper>
        </Grid>

        <Grid item xs={12}>
          <GlassPaper sx={{ p: 3, height: '400px' }}>
            <Typography variant="h6" gutterBottom sx={{ color: 'rgba(255, 255, 255, 0.7)' }}>
              Messages by Hour
            </Typography>
            <Box sx={{ height: 'calc(100% - 40px)' }}>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={analytics.messagesByHour}>
                  <CartesianGrid strokeDasharray="3 3" stroke="rgba(255, 255, 255, 0.1)" />
                  <XAxis 
                    dataKey="hour" 
                    stroke="#fff"
                    tick={{ fill: '#fff' }}
                    axisLine={{ stroke: 'rgba(255, 255, 255, 0.1)' }}
                  />
                  <YAxis 
                    stroke="#fff"
                    tick={{ fill: '#fff' }}
                    axisLine={{ stroke: 'rgba(255, 255, 255, 0.1)' }}
                  />
                  <Tooltip
                    contentStyle={{ 
                      background: 'rgba(26, 31, 53, 0.95)', 
                      border: '1px solid rgba(255, 255, 255, 0.1)',
                      borderRadius: '8px',
                      boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
                    }}
                    itemStyle={{ color: '#fff' }}
                  />
                  <Bar 
                    dataKey="count" 
                    fill="#00f2fe"
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </Box>
          </GlassPaper>
        </Grid>
      </Grid>
    </Box>
  );
}

export default AnalyticsDashboard;